using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Globalization;
namespace InputAtlas {
public sealed class KeyboardHeatView:FrameworkElement {
 sealed class Key {public int Id;public string Label;public Rect Rect;}
 readonly List<Key> keys=new List<Key>();readonly Dictionary<int,double> counts;readonly List<KeyValuePair<Rect,string>> hits=new List<KeyValuePair<Rect,string>>();readonly bool zh;readonly int palette,extraCount;readonly double peak;double emphasis;
 public KeyboardHeatView(Dictionary<int,double> values,bool chinese):this(values,chinese,0,MouseHeatScale.DefaultEmphasis){}
 public KeyboardHeatView(Dictionary<int,double> values,bool chinese,int colors,double contrast){counts=values;zh=chinese;palette=colors==1?1:0;emphasis=MouseHeatScale.Clamp(contrast);peak=counts.Count==0?0:Math.Max(0,counts.Values.Max());Build();var extra=counts.Keys.Where(k=>counts[k]>0&&!keys.Any(key=>key.Id==k)&&ShortcutCodec.KeyName(k)!=null).OrderBy(k=>k).ToList();extraCount=extra.Count;double x=0,y=7.1;foreach(int id in extra){string label=ShortcutCodec.KeyName(id);double width=Math.Max(1.65,Math.Min(3.5,1+label.Length*.17));if(x+width>23.4){x=0;y++;}Add(id,label,x,y,width);x+=width;}Height=keys.Max(k=>k.Rect.Bottom)*42+62;MouseMove+=(s,e)=>{var p=e.GetPosition(this);var item=hits.FirstOrDefault(h=>h.Key.Contains(p));ToolTip=item.Value;};}
 public Color KeyColor(int id){double n;counts.TryGetValue(id,out n);return n<=0?Theme.Empty:MouseHeatColors.Sample(MouseHeatScale.Normalize(n,peak,emphasis),palette);}
 public static Brush KeyText(Color background){Func<byte,double> channel=v=>{double s=v/255.0;return s<=.04045?s/12.92:Math.Pow((s+.055)/1.055,2.4);};double luminance=.2126*channel(background.R)+.7152*channel(background.G)+.0722*channel(background.B);return (luminance+.05)/.05>=1.05/(luminance+.05)?Brushes.Black:Brushes.White;}
 public string KeyTooltip(int id){var key=keys.FirstOrDefault(k=>k.Id==id);double n;counts.TryGetValue(id,out n);string result=(key==null?ShortcutCodec.KeyName(id):key.Label)+": "+n.ToString("N0")+(zh?" 次":" presses");if(id>=124&&id<=135)result+=zh?"\nWindows 扩展功能键":"\nWindows extended function key";return result;}
 public void SetEmphasis(double value){value=MouseHeatScale.Clamp(value);if(Math.Abs(value-emphasis)<.000001)return;emphasis=value;InvalidateVisual();}
 void Add(int id,string label,double x,double y,double w=1,double h=1){keys.Add(new Key{Id=id,Label=label,Rect=new Rect(x,y,w,h)});}
 void Build(){Add(27,"Esc",0,0);for(int i=0;i<12;i++)Add(112+i,"F"+(i+1),2+i+(i>=4?.3:0)+(i>=8?.3:0),0);int[] top={192,49,50,51,52,53,54,55,56,57,48,189,187};string[] topLabels={"~","1","2","3","4","5","6","7","8","9","0","-","="};for(int i=0;i<top.Length;i++)Add(top[i],topLabels[i],i,1.35);Add(8,"Backspace",13,1.35,2);
  Add(44,"PrtSc",15.7,0);Add(145,"Scroll",16.7,0);Add(19,"Pause",17.7,0);Add(9,"Tab",0,2.35,1.5);string q="QWERTYUIOP";for(int i=0;i<q.Length;i++)Add(q[i],q[i].ToString(),1.5+i,2.35);Add(219,"[",11.5,2.35);Add(221,"]",12.5,2.35);Add(220,"\\",13.5,2.35,1.5);
  Add(20,"Caps",0,3.35,1.8);string a="ASDFGHJKL";for(int i=0;i<a.Length;i++)Add(a[i],a[i].ToString(),1.8+i,3.35);Add(186,";",10.8,3.35);Add(222,"'",11.8,3.35);Add(13,"Enter",12.8,3.35,2.2);
  Add(160,"Shift",0,4.35,2.3);string z="ZXCVBNM";for(int i=0;i<z.Length;i++)Add(z[i],z[i].ToString(),2.3+i,4.35);Add(188,",",9.3,4.35);Add(190,".",10.3,4.35);Add(191,"/",11.3,4.35);Add(161,"Shift",12.3,4.35,2.7);
  Add(162,"Ctrl",0,5.35,1.25);Add(91,"Win",1.25,5.35,1.25);Add(164,"Alt",2.5,5.35,1.25);Add(32,"Space",3.75,5.35,6.25);Add(165,"Alt",10,5.35,1.25);Add(92,"Win",11.25,5.35,1.25);Add(93,"Menu",12.5,5.35,1.25);Add(163,"Ctrl",13.75,5.35,1.25);
  int[] nav={45,36,33,46,35,34};string[] names={"Ins","Home","PgUp","Del","End","PgDn"};for(int i=0;i<6;i++)Add(nav[i],names[i],15.7+i%3,1.35+i/3);Add(38,"↑",16.7,4.35);Add(37,"←",15.7,5.35);Add(40,"↓",16.7,5.35);Add(39,"→",17.7,5.35);
  Add(144,"Num",19.4,1.35);Add(111,"/",20.4,1.35);Add(106,"*",21.4,1.35);Add(109,"-",22.4,1.35);for(int row=0;row<3;row++)for(int col=0;col<3;col++){int n=(2-row)*3+col+1;Add(96+n,n.ToString(),19.4+col,2.35+row);}Add(107,"+",22.4,2.35,1,2);Add(269,"Enter",22.4,4.35,1,2);Add(96,"0",19.4,5.35,2);Add(110,".",21.4,5.35);
 }
 void Text(DrawingContext dc,string label,double x,double y,double size,Brush color){dc.DrawText(new FormattedText(label,CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),size,color,VisualTreeHelper.GetDpi(this).PixelsPerDip),new Point(x,y));}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);double u=Math.Max(1,(ActualWidth-12)/23.4),h=42;hits.Clear();foreach(var key in keys){Color fill=KeyColor(key.Id);var rect=new Rect(6+key.Rect.X*u,8+key.Rect.Y*h,Math.Max(2,key.Rect.Width*u-4),key.Rect.Height*h-4);dc.DrawRoundedRectangle(new SolidColorBrush(fill),new Pen(Theme.Get("Stroke"),.8),rect,4,4);Brush ink=KeyText(fill);double size=Math.Max(8,Math.Min(13,u*.35)),dpi=VisualTreeHelper.GetDpi(this).PixelsPerDip;var text=new FormattedText(key.Label,CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),size,ink,dpi);if(text.Width>rect.Width-8)text=new FormattedText(key.Label,CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),Math.Max(6,size*Math.Max(1,rect.Width-8)/Math.Max(1,text.Width)),ink,dpi);dc.DrawText(text,new Point(rect.X+(rect.Width-text.Width)/2,rect.Y+(rect.Height-text.Height)/2));hits.Add(new KeyValuePair<Rect,string>(rect,KeyTooltip(key.Id)));}
  if(extraCount>0)Text(dc,zh?"其他按键":"Additional keys",6,6.65*h+4,11,Theme.Muted);double bottom=keys.Max(k=>k.Rect.Bottom)*h+17,length=Math.Min(220,ActualWidth*.4),left=Math.Max(6,ActualWidth-length-12);Text(dc,zh?"灰色：未使用":"Gray: unused",6,bottom+1,11,Theme.Muted);for(int i=0;i<120;i++){double ratio=i/119.0;var brush=new SolidColorBrush(MouseHeatColors.Sample(MouseHeatScale.Normalize(ratio,1,emphasis),palette));dc.DrawRectangle(brush,null,new Rect(left+i*length/120,bottom,length/120+1,8));}Text(dc,">0%",left,bottom+11,10,Theme.Muted);Text(dc,"50%",left+length/2-10,bottom+11,10,Theme.Muted);Text(dc,"100%",left+length-26,bottom+11,10,Theme.Muted);
 }
}
public static class MouseHeatColors {
 static readonly Color[] Thermal={Color.FromRgb(12,5,29),Color.FromRgb(45,11,85),Color.FromRgb(99,24,123),Color.FromRgb(161,38,104),Color.FromRgb(215,66,66),Color.FromRgb(249,121,24),Color.FromRgb(253,184,39),Color.FromRgb(255,241,171)};
 public static Color Sample(double t,int palette){if(palette==1){t=Math.Max(0,Math.Min(1,t));double p=t*(Thermal.Length-1);int i=Math.Min(Thermal.Length-2,(int)p);double k=p-i;Color a=Thermal[i],b=Thermal[i+1];return Color.FromRgb((byte)(a.R+(b.R-a.R)*k),(byte)(a.G+(b.G-a.G)*k),(byte)(a.B+(b.B-a.B)*k));}
  double red=Math.Max(0,Math.Min(1,1.5-Math.Abs(4*t-3))),green=Math.Max(0,Math.Min(1,1.5-Math.Abs(4*t-2))),blue=Math.Max(0,Math.Min(1,1.5-Math.Abs(4*t-1)));return Color.FromRgb((byte)(255*red),(byte)(255*green),(byte)(80+175*blue));
 }
}
public static class MouseHeatScale {
 public const double DefaultEmphasis=.65,MinimumEmphasis=.35,MaximumEmphasis=1.5;
 public static double Clamp(double value){return Double.IsNaN(value)||Double.IsInfinity(value)?DefaultEmphasis:Math.Max(MinimumEmphasis,Math.Min(MaximumEmphasis,value));}
 public static double Normalize(double value,double peak,double emphasis){if(value<=0||peak<=0||Double.IsNaN(value)||Double.IsNaN(peak)||Double.IsInfinity(peak))return 0;return Math.Pow(Math.Min(1,value/peak),Clamp(emphasis));}
}
public sealed class MouseHeatView:FrameworkElement {
 readonly List<Dictionary<string,object>> cells;readonly bool zh;readonly int palette;readonly Dictionary<int,double> density;static readonly double[] kernel=BuildKernel();readonly double[] values=new double[384*216];double peak,emphasis;BitmapSource image;Rect map;
 static double[] BuildKernel(){var v=new double[441];for(int y=-10;y<=10;y++)for(int x=-10;x<=10;x++)v[(y+10)*21+x+10]=Math.Exp(-(x*x+y*y)/22.0);return v;}
 public MouseHeatView(InputMapData data,string selected,bool chinese):this(data,selected,chinese,0){}
 public MouseHeatView(InputMapData data,string selected,bool chinese,int colors):this(data,selected,chinese,colors,MouseHeatScale.DefaultEmphasis){}
 public MouseHeatView(InputMapData data,string selected,bool chinese,int colors,double contrast){zh=chinese;palette=colors==1?1:0;emphasis=MouseHeatScale.Clamp(contrast);cells=data.Cells.Where(r=>selected=="all"||Convert.ToString(r["display"])==selected).ToList();density=cells.GroupBy(r=>(int)Store.Number(r["y"])*128+(int)Store.Number(r["x"])).ToDictionary(g=>g.Key,g=>g.Sum(r=>Store.Number(r["n"])));MouseMove+=(s,e)=>{var p=e.GetPosition(this);if(map.Contains(p)){int x=Math.Min(127,(int)((p.X-map.Left)/map.Width*128)),y=Math.Min(71,(int)((p.Y-map.Top)/map.Height*72));ToolTip=CellTooltip(x,y);}else ToolTip=null;};BuildDensity();BuildImage();}
 public string CellTooltip(int x,int y){double n;density.TryGetValue(Math.Max(0,Math.Min(71,y))*128+Math.Max(0,Math.Min(127,x)),out n);return (zh?"此区域点击：":"Clicks in this cell: ")+n.ToString("N0");}
 public void SetEmphasis(double value){value=MouseHeatScale.Clamp(value);if(Math.Abs(value-emphasis)<.000001)return;emphasis=value;BuildImage();InvalidateVisual();}
 protected override Size MeasureOverride(Size available){return new Size(Double.IsInfinity(available.Width)?800:available.Width,Math.Max(290,Math.Min(660,available.Width*.5625+80)));}
 void BuildDensity(){int width=384,height=216;foreach(var c in density){int x=c.Key%128*3+1,y=c.Key/128*3+1;for(int dy=-10;dy<=10;dy++)for(int dx=-10;dx<=10;dx++){int a=x+dx,b=y+dy;if(a>=0&&a<width&&b>=0&&b<height)values[b*width+a]+=c.Value*kernel[(dy+10)*21+dx+10];}}peak=values.Max();}
 void BuildImage(){int width=384,height=216;var pixels=new byte[width*height*4];for(int i=0;i<values.Length;i++){Color color=MouseHeatColors.Sample(MouseHeatScale.Normalize(values[i],peak,emphasis),palette);pixels[i*4]=color.B;pixels[i*4+1]=color.G;pixels[i*4+2]=color.R;pixels[i*4+3]=255;}image=BitmapSource.Create(width,height,96,96,PixelFormats.Bgra32,null,pixels,width*4);image.Freeze();}
 void Text(DrawingContext dc,string label,double x,double y,double size=11){dc.DrawText(new FormattedText(label,CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),size,Theme.Text,VisualTreeHelper.GetDpi(this).PixelsPerDip),new Point(x,y));}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);double w=Math.Max(100,ActualWidth-22),h=Math.Max(160,ActualHeight-85);map=new Rect(10,8,w,h);dc.DrawRoundedRectangle(Brushes.Black,new Pen(Brushes.Gray,2),new Rect(7,5,w+6,h+6),6,6);dc.DrawImage(image,map);string label=(zh?"已记录点击位置：":"Recorded click locations: ")+density.Values.Sum().ToString("N0");Text(dc,label,10,h+25,12);
  double length=Math.Min(240,w*.45),left=10+w-length;for(int i=0;i<120;i++){double ratio=i/119.0;var brush=new SolidColorBrush(MouseHeatColors.Sample(MouseHeatScale.Normalize(ratio,1,emphasis),palette));dc.DrawRectangle(brush,null,new Rect(left+i*length/120,h+28,length/120+1,9));}Text(dc,"0%",left,h+40);Text(dc,"50%",left+length/2-10,h+40);Text(dc,"100%",left+length-29,h+40);
 }
}
